import { Component, OnInit, ViewChild } from '@angular/core';
import { SharedIonic } from '../../../../core/common/SharedIonic';
import { GResponse } from '../../../../core/common/GResponse';
import { Router } from '@angular/router';
import { ToastController, LoadingController, AlertController, IonContent, MenuController } from '@ionic/angular';
import { ICommonQuestionViewModel } from 'src/app/data/model/site/SliderModel';
import { SliderService } from 'src/app/data/service/site/Slider.service';
import { SafeUrl } from '@angular/platform-browser';
import { G } from '../../../../core/common/G';
import { SiteLanguageService } from '../../../../core/i18n/site-language.service';

@Component({
  selector: 'app-common-questions',
  templateUrl: './common-questions.component.html',
  styleUrls: ['./common-questions.component.scss']
})
export class CommonQuestionsComponent implements OnInit {

  @ViewChild(IonContent) content: IonContent;
  list: ICommonQuestionViewModel[] = [];
  isLoading = true;
  queryText = '';
  showSearchbar = false;
  instagram: string | SafeUrl = '';
  twiter: string | SafeUrl = '';
  facebook: string | SafeUrl = '';
  telegram: string | SafeUrl = '';
  pinterest: string | SafeUrl = '';
  aparat: string | SafeUrl = '';
  discord: string | SafeUrl = '';
  youtube: string | SafeUrl = '';
  twitch: string | SafeUrl = '';
  linkedin: string | SafeUrl = '';

  constructor(
    private siteService: SliderService,
    public toastController: ToastController,
    public loadingController: LoadingController,
    public alertController: AlertController,
    private menuCtrl: MenuController,
    private router: Router,
    public language: SiteLanguageService) { }

  toggleAppMenu() {
    this.menuCtrl.toggle('start');
  }

  goTop() {
    this.content.scrollToTop(3000);
  }

  forwardUrl(url: string) {
    window.location.href = url;
  }

  ngOnInit(): void {

    this.instagram = G.Instagram;
    this.twiter = G.Twiter;
    this.facebook = G.Facebook;
    this.telegram = G.Telegram;
    this.youtube = G.Youtube;
    this.pinterest = G.Pinterest;
    this.linkedin = G.Linkedin;
    this.twitch = G.Twitch;
    this.aparat = G.Aparat;
    this.discord = G.Discord;
  }

  onNavigate(url: string) {

    this.router.navigateByUrl(url);
  }

  onCancel() {
    this.showSearchbar = false;
  }

  search() {

    if (this.queryText == null || this.queryText.length < 1) {
      return;
    }

    this.router
      .navigate(
        ['Home', 'Search'],
        {
          queryParams:
          {
            title: this.queryText
          }
        });
  }

  onClick(id: number | string) {

    this.router
      .navigate(
        ['/Home', 'Search'],
        {
          queryParams:
          {
            categoryIds: [id],
            page: 1
          }
        });
  }

  doRefresh(event) {

    setTimeout(() => {

      location.reload();

      event.target.complete();
    }, 2000);
  }

  ionViewWillEnter() {

    this.getData();
  }

  getData() {

    SharedIonic.loading(this.loadingController);

    this.siteService.GetAllCommonQuestions().subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (GResponse.SuccessStatus === res.status) {

          this.list = [];
          res.data.forEach(q => {
            if (q.isActive) {
              this.list.push(q);
            }
          });
          this.isLoading = false;
        } else {
          SharedIonic.toast(this.toastController, 'موردی یافت نشد');
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

}
